<script setup lang="ts">
import { Icon } from '@iconify/vue'
import type { Ref } from 'vue'
import CourseDonationModal from '~/components/donation/CourseDonationModal.vue'
import CoursePointClaimCard from '~/components/learn/course/points/CoursePointClaimCard.vue'
import CourseClaimWidget from '~/components/learn/course/points/CourseClaimWidget.vue'
import CampaignCreateModal from '~/components/learn/course/points/CampaignCreateModal.vue'
import CampaignManageModal from '~/components/learn/course/points/CampaignManageModal.vue'
import WithdrawModal from '~/components/learn/course/points/WithdrawModal.vue'
import type { CourseDonation } from '~/composables/useCourseDonations'
import { useCourseClaimable } from '~/composables/useCourseClaimable'
const props = withDefaults(defineProps<{ course: any; isCourseAdmin?: boolean }>(), { isCourseAdmin: false })
const authStore = useAuthStore(); const sweetAlert = useSweetAlert(); const showDonationModal = ref(false); const showCreate = ref(false); const showManage = ref(false); const showWithdraw = ref(false); const donations = ref<CourseDonation[]>([]); const claimBump = ref(false); const activeTab = ref<'claims' | 'ledger'>('claims'); const loadedTabs = ref({ claims: false, ledger: false })
const courseRef = computed(() => props.course.id); const { account, campaigns, ownerCampaigns, transactions, isClaiming, fetchAccount, fetchAvailableCampaigns, fetchOwnerCampaigns, fetchTransactions, claimCampaign } = useCoursePoints(courseRef); const { fetchCourseDonations } = useCourseDonations(); const { claims, claimsPagination, claimsSummary, claimsLoading, claimsError, fetchClaims } = useCourseClaimable(courseRef)
const tabs = computed(() => [{ key: 'claims' as const, label: 'ประวัติการกดรับ', icon: 'mdi:history' }, ...(props.isCourseAdmin ? [{ key: 'ledger' as const, label: 'ประวัติแต้มกองทุน', icon: 'mdi:swap-vertical' }] : [])]); const approvedPointDonations = computed(() => donations.value.filter(d => d.donation_type === 'point' && ['approved', 'completed'].includes(d.status))); const fundBalance = computed(() => account.value?.balance ?? 0); const distributed = computed(() => account.value?.total_distributed ?? 0); const manualCampaigns = computed(() => ownerCampaigns.value.filter(c => c.campaign_type === 'manual_claim')); const hasActiveManual = computed(() => manualCampaigns.value.some(c => c.status === 'active'))
const useCountUp = (target: Ref<number>) => { const display = ref(0); let frame = 0; watch(target, value => { const from = display.value; const start = performance.now(); cancelAnimationFrame(frame); const tick = (now: number) => { const p = Math.min(1, (now - start) / 600); display.value = Math.round(from + (value - from) * (1 - Math.pow(1 - p, 3))); if (p < 1) frame = requestAnimationFrame(tick) }; frame = requestAnimationFrame(tick) }, { immediate: true }); return display }
const balanceDisplay = useCountUp(fundBalance); const supportersDisplay = useCountUp(computed(() => approvedPointDonations.value.length)); const distributedDisplay = useCountUp(distributed)
const loadSupportData = async () => { await Promise.all([fetchAccount(), fetchAvailableCampaigns(), props.isCourseAdmin ? fetchOwnerCampaigns() : Promise.resolve(), fetchCourseDonations(Number(props.course.id), { per_page: 5 }).then((r: any) => { donations.value = r?.data || [] })]) }
// การกดรับหนึ่งครั้งแตะทั้งสองแท็บ (claims 1 แถว, ledger 2 แถว) รีเฟรชเฉพาะแท็บที่โหลดไปแล้ว
const refreshHistory = () => { if (loadedTabs.value.claims) fetchClaims(); if (loadedTabs.value.ledger) fetchTransactions() }; const claim = async (id: number) => { const result: any = await claimCampaign(id).catch((e: any) => ({ success: false, message: e?.data?.message })); if (!result?.success) { sweetAlert.toast(result?.message || 'ไม่สามารถรับแต้มได้', 'error'); return } sweetAlert.toast(`+${result.points_received} แต้ม!`); refreshHistory(); claimBump.value = true; setTimeout(() => claimBump.value = false, 800) }
const formatClaimDate = (value: string) => value ? new Date(value).toLocaleDateString('th-TH', { day: 'numeric', month: 'short', year: 'numeric' }) : ''
// กองทุนเก็บ amount เป็นค่าบวกเสมอ ทิศทางจริงอ่านจากส่วนต่างของยอดคงเหลือ
const ledgerLabels: Record<string, string> = { lesson_income: 'รายได้จากบทเรียน', owner_withdraw: 'เจ้าของถอนแต้ม', campaign_debit: 'หักเข้ารอบแจกแต้ม', student_claim: 'นักเรียนกดรับแต้ม', refund: 'คืนแต้ม', campaign_reserve: 'กันแต้มไว้สำหรับรอบแจก', campaign_release: 'คืนแต้มจากรอบแจก', donation_point_credit: 'รับบริจาคแต้ม', donation_cash_credit: 'รับบริจาคเป็นเงิน', donation_reserve: 'กันแต้มบริจาคไว้ให้กดรับ', claim_share: 'ส่วนแบ่งรายวิชาจากการกดรับ', allocation_in: 'รับจัดสรรจากโรงเรียน', ad_revenue: 'รายได้จากโฆษณา', withdrawal_reserve: 'กันแต้มไว้รอถอน', withdrawal_release: 'คืนแต้มจากคำขอถอน', withdrawal_paid: 'จ่ายแต้มตามคำขอถอน' }
const ledgerLabel = (tx: any) => ledgerLabels[tx?.type] ?? tx?.type ?? 'รายการแต้ม'
const ledgerDelta = (tx: any) => { const before = Number(tx?.balance_before); const after = Number(tx?.balance_after); return Number.isFinite(before) && Number.isFinite(after) ? after - before : Number(tx?.amount ?? 0) }
const ledgerBalance = (tx: any) => { const after = Number(tx?.balance_after); return Number.isFinite(after) ? after.toLocaleString() : '' }
watch(activeTab, async tab => { if (tab === 'ledger' && !props.isCourseAdmin) { activeTab.value = 'claims'; return } if (loadedTabs.value[tab]) return; loadedTabs.value[tab] = true; if (tab === 'claims') await fetchClaims(); else await fetchTransactions() }, { immediate: true }); onMounted(loadSupportData)
</script>
<template>
<section class="rounded-2xl border border-gray-200 bg-white p-5 shadow-sm dark:border-gray-700 dark:bg-gray-800 sm:p-6"><header class="flex flex-wrap items-center justify-between gap-3"><div class="flex items-center gap-3"><span class="flex h-11 w-11 items-center justify-center rounded-xl bg-vikinger-purple/10 text-vikinger-purple"><Icon icon="mdi:hand-heart-outline" class="h-6 w-6" /></span><h2 class="text-lg font-bold text-gray-900 dark:text-white">สนับสนุน &amp; รับแต้ม</h2></div><button v-if="course.donation_enabled !== false" type="button" class="min-h-[44px] sm:min-h-0 rounded-xl bg-vikinger-purple px-4 py-2 text-sm font-semibold text-white" @click="showDonationModal = true">บริจาคแต้ม</button></header>
<div class="mt-5 grid grid-cols-3 gap-3 border-y border-gray-100 py-4 dark:border-gray-700"><div><p class="text-xs text-gray-500 dark:text-gray-400">แต้มในกองทุน</p><p class="mt-1 text-xl font-bold text-gray-900 transition dark:text-white" :class="claimBump ? 'animate-pulse scale-110' : ''">{{ balanceDisplay.toLocaleString() }} แต้ม</p></div><div><p class="text-xs text-gray-500 dark:text-gray-400">ผู้สนับสนุน</p><p class="mt-1 text-xl font-bold text-gray-900 dark:text-white">{{ supportersDisplay.toLocaleString() }}</p></div><div><p class="text-xs text-gray-500 dark:text-gray-400">แจกแล้ว</p><p class="mt-1 text-xl font-bold text-gray-900 dark:text-white">{{ distributedDisplay.toLocaleString() }}</p></div></div>
<template v-if="isCourseAdmin"><p class="mt-5 text-sm text-gray-500 dark:text-gray-400">กองทุนของคุณเก็บแต้มจากผู้สนับสนุน — เปิดรอบแจกแต้มให้นักเรียนกดรับ</p><div class="mt-3 grid gap-3 sm:grid-cols-3"><button v-for="action in [{ icon: 'mdi:star-plus-outline', title: 'เปิดให้นักเรียนรับแต้ม', description: 'เปลี่ยนแต้มในกองทุนเป็นการ์ดให้นักเรียนกดรับ', click: () => showCreate = true }, { icon: 'mdi:playlist-star', title: 'จัดการรอบแจกแต้ม', description: 'พัก/จบรอบแจกแต้มที่กำลังใช้อยู่', click: () => showManage = true }, { icon: 'mdi:bank-transfer-out', title: 'ถอนแต้ม', description: 'ถอนแต้มออกเป็นแต้มส่วนตัว', click: () => showWithdraw = true }]" :key="action.title" type="button" class="group relative cursor-pointer rounded-2xl border border-gray-200 bg-white p-5 text-left transition hover:-translate-y-1 hover:border-vikinger-purple hover:shadow-lg dark:border-gray-700 dark:bg-gray-800/60" @click="action.click"><Icon :icon="action.icon" class="h-10 w-10 text-vikinger-purple" /><b class="mt-3 block text-gray-900 dark:text-white">{{ action.title }}</b><span class="mt-1 block text-xs text-gray-500 dark:text-gray-400">{{ action.description }}</span><template v-if="action.title === 'เปิดให้นักเรียนรับแต้ม' && fundBalance > 0 && !hasActiveManual"><span class="absolute right-4 top-4 h-3 w-3 rounded-full bg-yellow-400"><span class="absolute inset-0 h-3 w-3 animate-ping rounded-full bg-yellow-400" /></span><small class="mt-3 inline-block rounded-full bg-yellow-100 px-2 py-1 text-xs text-yellow-700">รอเปิดให้รับ</small></template></button></div></template>
<section class="mt-5"><h3 class="font-bold text-gray-900 dark:text-white">ผู้สนับสนุนล่าสุด</h3><TransitionGroup name="donate-list" tag="div" class="mt-3 space-y-2"><div v-for="donation in approvedPointDonations" :key="donation.id" class="flex items-center justify-between rounded-xl bg-gray-50 px-3 py-2.5 dark:bg-gray-900/40"><span class="text-sm text-gray-700 dark:text-gray-200">{{ donation.donor_display_name || 'ผู้สนับสนุนไม่ประสงค์ออกนาม' }}</span><span class="text-sm font-bold text-vikinger-purple">{{ donation.points_amount }} แต้ม</span></div></TransitionGroup><p v-if="!approvedPointDonations.length" class="mt-3 text-sm text-gray-500 dark:text-gray-400">ยังไม่มีคนสนับสนุน ลองแชร์คอร์สให้เพื่อนดูสิ 🚀</p></section>
<section v-if="campaigns.length" class="mt-5 border-b border-gray-100 pb-5 dark:border-gray-700"><div><h3 class="flex items-center gap-2 font-bold text-gray-900 dark:text-white"><Icon icon="mdi:star-circle" class="h-5 w-5 text-vikinger-purple" />รอบแจกแต้มจากกองทุนวิชา</h3><p class="mt-0.5 text-xs text-gray-500 dark:text-gray-400">แต้มจากรายได้ของวิชา ไม่ใช่จากเงินบริจาค</p></div><div class="mt-3 grid gap-3"><CoursePointClaimCard v-for="campaign in campaigns" :key="campaign.id" :campaign="campaign" :is-claiming="isClaiming === campaign.id" @claim="claim" /></div></section>
<section class="mt-5 rounded-2xl border border-gray-100 dark:border-gray-700"><div class="overflow-x-auto border-b border-gray-100 p-3 dark:border-gray-700"><div class="flex min-w-max gap-2"><button class="min-h-[44px] sm:min-h-0" v-for="tab in tabs" :key="tab.key" type="button" :class="['flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-medium transition-colors', activeTab === tab.key ? 'bg-vikinger-purple text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200 dark:bg-gray-700/60 dark:text-gray-300 dark:hover:bg-gray-700']" @click="activeTab = tab.key"><Icon :icon="tab.icon" class="h-4 w-4" />{{ tab.label }}</button></div></div><div class="p-4"><div v-if="activeTab === 'claims'"><p class="text-sm text-gray-600 dark:text-gray-300">คุณรับแต้มแล้ว {{ claimsSummary.my_claims_count }} ครั้ง รวม {{ claimsSummary.my_points_total.toLocaleString() }} แต้ม · ทั้งหมด {{ claimsSummary.total_claims }} รายการ</p><div v-if="claimsLoading && !claims.length" class="py-6 text-center text-sm text-gray-500 dark:text-gray-400">กำลังโหลด...</div><div v-else-if="claims.length" class="mt-3 space-y-2"><div v-for="item in claims" :key="item.id" :class="['flex items-center gap-3 rounded-xl border border-transparent p-3 dark:border-transparent', item.is_mine ? 'bg-indigo-50 ring-1 ring-indigo-200 dark:bg-indigo-900/20 dark:ring-indigo-700' : 'bg-gray-50 dark:bg-gray-900/40']"><div class="flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-vikinger-purple/10 font-bold text-vikinger-purple dark:bg-vikinger-purple/20"><img v-if="item.claimer_avatar" :src="item.claimer_avatar" class="h-full w-full object-cover" /><span v-else>{{ (item.claimer_name || '?').charAt(0).toUpperCase() }}</span></div><div class="min-w-0 flex-1"><p class="truncate text-sm text-gray-700 dark:text-gray-200">{{ item.claimer_name || 'ผู้เรียน' }} กดรับจาก {{ item.donor_display_name }}</p><p class="text-xs text-gray-500 dark:text-gray-400">{{ formatClaimDate(item.claimed_at) }}</p></div><strong class="text-sm text-emerald-600 dark:text-emerald-400">+{{ item.amount_claimer }} แต้ม</strong></div></div><p v-else class="py-6 text-center text-sm text-gray-500 dark:text-gray-400">ยังไม่มีประวัติการรับแต้ม</p><p v-if="claimsError" class="mt-2 text-xs text-gray-500 dark:text-gray-400">ไม่สามารถโหลดประวัติได้ในขณะนี้</p><button v-if="claimsPagination.has_more" type="button" :disabled="claimsLoading" class="min-h-[44px] sm:min-h-0 mt-3 rounded-xl bg-gray-100 px-4 py-2 text-sm text-gray-700 transition disabled:cursor-not-allowed disabled:opacity-50 dark:bg-gray-700/60 dark:text-gray-200" @click="fetchClaims(true)">{{ claimsLoading ? 'กำลังโหลด...' : 'โหลดเพิ่ม' }}</button></div><div v-else-if="activeTab === 'ledger'"><div v-if="!transactions.length" class="py-8 text-center text-sm text-slate-500 dark:text-slate-400">ยังไม่มีประวัติรายการ</div><div v-for="transaction in transactions" :key="transaction.id" class="flex items-center justify-between gap-3 border-b border-slate-100 py-3 text-sm last:border-0 dark:border-slate-700"><div class="min-w-0"><p class="truncate text-gray-700 dark:text-gray-200">{{ ledgerLabel(transaction) }}</p><p class="mt-0.5 text-xs text-gray-400 dark:text-gray-500">{{ formatClaimDate(transaction.created_at) }}<span v-if="ledgerBalance(transaction)"> · คงเหลือ {{ ledgerBalance(transaction) }} แต้ม</span></p></div><strong v-if="ledgerDelta(transaction) !== 0" class="shrink-0" :class="ledgerDelta(transaction) > 0 ? 'text-emerald-600 dark:text-emerald-400' : 'text-red-500'">{{ ledgerDelta(transaction) > 0 ? '+' : '' }}{{ ledgerDelta(transaction).toLocaleString() }}</strong><span v-else class="shrink-0 text-xs text-gray-400 dark:text-gray-500">กันไว้ {{ Number(transaction.amount || 0).toLocaleString() }}</span></div></div></div></section>
<CourseClaimWidget class="mt-5" :course-id="Number(course.id)" @claimed="() => { loadSupportData(); refreshHistory() }" /><CourseDonationModal v-model:visible="showDonationModal" :course-id="Number(course.id)" :course-name="course.name" :course-owner-id="Number(course.user_id)" :balance="authStore.user?.points ?? authStore.user?.pp" @update:visible="loadSupportData" /><CampaignCreateModal v-if="isCourseAdmin" v-model:visible="showCreate" :course-id="course.id" :available-balance="account?.available_balance || 0" @created="loadSupportData" /><CampaignManageModal v-if="isCourseAdmin" v-model:visible="showManage" :course-id="course.id" @updated="loadSupportData" /><WithdrawModal v-if="isCourseAdmin" v-model:visible="showWithdraw" :course-id="course.id" @updated="loadSupportData" /></section>
</template>
<style scoped>.donate-list-enter-active,.donate-list-leave-active{transition:all .3s ease}.donate-list-enter-from,.donate-list-leave-to{opacity:0;transform:translateY(8px)}</style>
